import SwiftUI
import shared

// ---------------------------------------------------------------------------
// External SOCKS proxy mode — Settings UI + the connecting-UI status line.
// See ExternalProxyMode.swift for the transport invariant and
// docs/external-socks-proxy.md for the feature.
//
// All user-visible text goes through ExtProxyText below, which maps onto the
// generated L10n keys (prefix `ext_proxy_`, English source in the Android
// strings XML, regenerated by scripts/l10n/gen-l10n.mjs). Keeping every key in
// one place makes the cross-platform key reconciliation a one-file job.
//
// Validation is the SHARED rule set (commonMain ExternalTorProxy via iosMain
// IosExternalProxyStore.validate) — no IP parsing is duplicated here.
// Nothing here logs the host or port.
// ---------------------------------------------------------------------------

enum ExtProxyText {
    static var title: String { L10n.extProxyTitle }
    static var description: String { L10n.extProxyDescription }
    static var toggle: String { L10n.extProxyToggle }
    static var hostLabel: String { L10n.extProxyHostLabel }
    static var portLabel: String { L10n.extProxyPortLabel }
    static var errorHost: String { L10n.extProxyErrorHost }
    static var errorPort: String { L10n.extProxyErrorPort }
    static var errorSave: String { L10n.extProxyErrorSave }
    static var lanWarning: String { L10n.extProxyLanWarning }
    static var nextLaunchNote: String { L10n.extProxyNextLaunch }
    static var saved: String { L10n.extProxySaved }
    static var connectingPhase: String { L10n.extProxyConnecting }
    static var statusChecking: String { L10n.extProxyStatusChecking }
    static var statusReachable: String { L10n.extProxyStatusReachable }
    static var statusUnreachable: String { L10n.extProxyStatusUnreachable }
    static var statusInvalid: String { L10n.extProxyStatusInvalid }
    static var statusUnreadable: String { L10n.extProxyStatusUnreadable }

    static func status(_ s: ExtProxyStatus) -> String? {
        switch s {
        case .off: return nil
        case .checking: return statusChecking
        case .reachable: return statusReachable
        case .unreachable: return statusUnreachable
        case .invalid: return statusInvalid
        case .unreadable: return statusUnreadable
        }
    }
}

/// One caption line under the connecting status, present whenever this process
/// is in external proxy mode, so the user always sees that their own proxy (not
/// the embedded Tor) is in use and whether it answers. a11y id `ext_proxy_status`.
/// Rendered only by surfaces that are mutually exclusive on screen (the
/// ContactListView placeholder vs its relay-trouble banner), so the id stays
/// unique.
struct ExternalProxyStatusLine: View {
    @EnvironmentObject var appState: AppState

    var body: some View {
        if let text = ExtProxyText.status(appState.extProxyStatus) {
            Text(text)
                .font(.runeCaption)
                .foregroundColor(appState.extProxyStatus == .reachable || appState.extProxyStatus == .checking
                                 ? Color.runTextSecondary : Color.runError)
                .multilineTextAlignment(.center)
                .accessibilityIdentifier("ext_proxy_status")
        }
    }
}

/// Settings sheet: toggle + IP + port + Save. Applies at the NEXT launch.
/// NOT relay-gated — it must stay usable precisely when the relay is not.
struct ExternalProxySettingsView: View {
    let onClose: () -> Void

    @State private var enabled = false
    @State private var host = ""
    @State private var port = ""
    @State private var error: String?
    @State private var savedNote = false
    @State private var loaded = false

    private var store: IosExternalProxyStore { IosExternalProxyStore.shared }

    /// Live verdict for the LAN warning (shared rules).
    private var liveVerdict: Int32? {
        let h = host.trimmingCharacters(in: .whitespaces)
        guard enabled, !h.isEmpty, let p = Int32(port.trimmingCharacters(in: .whitespaces)) else { return nil }
        return store.validate(host: h, port: p)
    }

    var body: some View {
        NavigationStack {
            ZStack {
                Color.runBackground.ignoresSafeArea()
                Form {
                    Section {
                        Toggle(ExtProxyText.toggle, isOn: $enabled)
                            .tint(Color.runAccent)
                            .accessibilityIdentifier("settings_ext_proxy_toggle")
                            .onChange(of: enabled) { _ in error = nil; savedNote = false }
                    } footer: {
                        Text(ExtProxyText.description)
                            .font(.runeCaption)
                            .foregroundColor(Color.runTextSecondary)
                    }
                    .listRowBackground(Color.runSurface)

                    if enabled {
                        Section {
                            TextField(ExtProxyText.hostLabel, text: $host)
                                .keyboardType(.numbersAndPunctuation)
                                .textInputAutocapitalization(.never)
                                .autocorrectionDisabled(true)
                                .textContentType(nil)
                                .accessibilityIdentifier("settings_ext_proxy_host")
                                .onChange(of: host) { _ in error = nil; savedNote = false }
                            TextField(ExtProxyText.portLabel, text: $port)
                                .keyboardType(.numberPad)
                                .accessibilityIdentifier("settings_ext_proxy_port")
                                .onChange(of: port) { _ in error = nil; savedNote = false }
                        } footer: {
                            if liveVerdict == store.VALID_LAN {
                                Text(ExtProxyText.lanWarning)
                                    .font(.runeCaption)
                                    .foregroundColor(Color.runError)
                                    .accessibilityIdentifier("settings_ext_proxy_lan_warning")
                            }
                        }
                        .listRowBackground(Color.runSurface)
                    }

                    Section {
                        Button(L10n.commonSave) { save() }
                            .foregroundColor(Color.runAccent)
                            .accessibilityIdentifier("settings_ext_proxy_save")
                    } footer: {
                        VStack(alignment: .leading, spacing: 6) {
                            if let error {
                                Text(error)
                                    .font(.runeCaption)
                                    .foregroundColor(Color.runError)
                                    .accessibilityIdentifier("settings_ext_proxy_error")
                            }
                            if savedNote {
                                Text(ExtProxyText.saved)
                                    .font(.runeCaption)
                                    .foregroundColor(Color.runTextSecondary)
                                    .accessibilityIdentifier("settings_ext_proxy_saved")
                            }
                            Text(ExtProxyText.nextLaunchNote)
                                .font(.runeCaption)
                                .foregroundColor(Color.runTextSecondary)
                                .accessibilityIdentifier("settings_ext_proxy_next_launch")
                        }
                    }
                    .listRowBackground(Color.runSurface)
                }
                .scrollContentBackground(.hidden)
            }
            .navigationTitle(ExtProxyText.title)
            .navigationBarTitleDisplayMode(.inline)
            .runNavigationBarChrome()
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button(L10n.commonDone) { onClose() }
                        .foregroundColor(Color.runAccent)
                        .accessibilityIdentifier("settings_ext_proxy_done")
                }
            }
        }
        .onAppear(perform: load)
    }

    private func load() {
        guard !loaded else { return }
        loaded = true
        let r = store.read()
        switch r.state {
        case store.STATE_ON:
            enabled = true
            host = r.host ?? ""
            port = r.port > 0 ? String(r.port) : ""
        case store.STATE_INVALID:
            // A stored-but-unusable value is still "on" (fail closed) — show it
            // as on with empty fields so the user can fix or turn it off.
            enabled = true
        default:
            enabled = false
        }
    }

    private func save() {
        savedNote = false
        if !enabled {
            if store.clear() {
                error = nil
                savedNote = true
                LogBuffer.shared.append(level: "I", tag: "ExtProxy", message: "ext proxy: setting cleared (applies next launch)")
            } else {
                error = ExtProxyText.errorSave
            }
            return
        }
        let h = host.trimmingCharacters(in: .whitespaces)
        guard let p = Int32(port.trimmingCharacters(in: .whitespaces)) else {
            error = h.isEmpty ? ExtProxyText.errorHost : ExtProxyText.errorPort
            return
        }
        switch store.validate(host: h, port: p) {
        case store.INVALID_HOST:
            error = ExtProxyText.errorHost
        case store.INVALID_PORT:
            error = ExtProxyText.errorPort
        default:
            if store.save(host: h, port: p) {
                error = nil
                savedNote = true
                LogBuffer.shared.append(level: "I", tag: "ExtProxy", message: "ext proxy: setting saved (applies next launch)")
            } else {
                error = ExtProxyText.errorSave
            }
        }
    }
}
